/// <summary>
        /// Maps verified STAAD-global joint actions to actual IDEA member bases, load positions,
        /// application points, and active model-type components, then predicts IDEA equilibrium.
        /// </summary>

/// <summary>
        /// Exports the generic STAAD audit together with the actual IDEA mapping,
        /// applied mapped rows, active-component checks, and reconstructed equilibrium.
        /// </summary>

/// <summary>
        /// Builds a deterministic topology snapshot and accessible SVG diagram for one audited joint.
        /// The diagram uses the exact member bases and plate ownership used by force transformation.
        /// </summary>

/// <summary>
        /// Exports several joints as one provenance-controlled package containing a multi-sheet workbook,
        /// consolidated audit, detailed per-joint audits, topology diagrams, and a JSON manifest.
        /// </summary>

Arguments:
group =>
                {
                    IdeaStatiCaMemberForcesResult carrier = group.First(row =>
                        row.ContributionKind == IdeaStatiCaJointForceContributionKind.MemberEnd ||
                        row.ContributionKind == IdeaStatiCaJointForceContributionKind.MemberEndWithSharedEdgePlates);
                    return new IdeaStatiCaMemberForcesResult
                    {
                        JointId = carrier.JointId,
                        LoadCaseId = carrier.LoadCaseId,
                        LoadCaseName = carrier.LoadCaseName,
                        MemberId = carrier.MemberId,
                        IdeaMemberName = carrier.IdeaMemberName,
                        MemberEnd = carrier.MemberEnd,
                        ContributionKind = carrier.ContributionKind,
                        CombinedStaadMemberEndActionsGlobal = SumForces(
                            group.Select(row => row.CombinedStaadMemberEndActionsGlobal))
                    };
                }

